using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Windows.Forms;

namespace RcsMap {
 public static class HardwareTests {
  static int checks;
  static void Check(bool pass,string label){if(!pass)throw new Exception("hardware test: "+label);++checks;}
  static void Reject(Action action,string label){try{action();}catch{++checks;return;}throw new Exception("hardware should reject: "+label);}
  public static MapDocument Fixture(string kind="gpio_output"){
   var doc=MapDocument.Demo();doc.Version=8;var device=HardwareCatalog.Create(HardwareCatalog.Builtins().First(t=>t.DriverKind==kind));device.Configured=true;doc.Devices=new List<DeviceInstance>{device};return doc;
  }
  public static void Write(string folder){Directory.CreateDirectory(folder);foreach(string kind in new[]{"gpio_output","pwm_servo","team_cylinder","team_jy901"})File.WriteAllText(Path.Combine(folder,kind+".rcsmap.json"),Fixture(kind).Json(),new UTF8Encoding(false));var custom=Fixture();var template=HardwareTemplateDialog.CreateBase("custom");template.Parameters.Add(new DeviceParameter{Key="Output",Name="逻辑输出",Type="int",Default="0",Min=0,Max=1});template.Files.Add(new DeviceFile{Path="my_device.h",Content="#pragma once\nint my_device_command(float value);\n"});template.Files.Add(new DeviceFile{Path="my_device.c",Content="#include \"my_device.h\"\nint my_device_command(float value) { return value >= 0.0f; }\n"});template.Includes="#include \"my_device.h\"";template.Hooks.Command="return my_device_command(value);";template.Hooks.Done="return 1;";custom.Devices=new List<DeviceInstance>{HardwareCatalog.Create(template)};custom.Devices[0].Configured=true;File.WriteAllText(Path.Combine(folder,"custom.rcsmap.json"),custom.Json(),new UTF8Encoding(false));}
  public static void Run(string folder){
   Directory.CreateDirectory(folder);checks=0;var catalog=HardwareCatalog.Builtins();Check(catalog.Count>=4,"four real base/team templates");Check(catalog.Select(t=>t.Id).Distinct().Count()==catalog.Count,"unique builtin IDs");
   var legacy=MapDocument.Demo();string original=legacy.Json();Check(!original.Contains("Devices")&&!original.Contains("DeviceReferences"),"legacy fields omitted");Check(legacy.Clone().Json()==original,"legacy exact roundtrip");
   var doc=Fixture();var device=doc.Devices[0];Check(doc.Clone().Json()==doc.Json(),"v8 device snapshot roundtrip");string firstId=device.Id;device.Name="左侧输出";Check(doc.Clone().Devices[0].Id==firstId,"rename keeps ID");Check(HardwareRules.Validate(doc).Count==0,"valid complete GPIO device");
   var snapshot=device.Template;var external=HardwareCatalog.Snapshot(snapshot);external.Note="outside changed";Check(HardwareCatalog.Hash(snapshot)!=HardwareCatalog.Hash(external)&&device.TemplateSha256==HardwareCatalog.Hash(snapshot),"snapshot pinned against external edits");
   var broken=doc.Clone();broken.Devices[0].Template.Note="tampered";Reject(()=>broken.StructuralCheck(),"changed snapshot SHA");broken=doc.Clone();broken.Version=7;Reject(()=>broken.StructuralCheck(),"new device in old schema");broken=doc.Clone();broken.Devices.Add(broken.Devices[0]);Reject(()=>broken.StructuralCheck(),"duplicate instance ID");broken=doc.Clone();broken.Devices[0].Values["undefined"]="1";Reject(()=>broken.StructuralCheck(),"unknown parameter");
   var p=device.Template.Parameters.First(x=>x.Key=="Pin");Reject(()=>HardwareRules.ParameterValue(p,"16"),"pin range");Reject(()=>HardwareRules.ParameterValue(device.Template.Parameters.First(x=>x.Key=="Port"),"GPIOA;danger"),"identifier injection");
   var unready=doc.Clone();unready.Devices[0].Configured=false;Check(HardwareRules.Validate(unready).Any(e=>e.Contains("尚未确认")),"unconfigured device blocks export");
   var twice=doc.Clone();var second=HardwareCatalog.Create(device.Template);second.Configured=true;twice.Devices.Add(second);Check(HardwareRules.Validate(twice).Any(e=>e.Contains("争用资源")),"GPIO conflict before generation");second.Values["Pin"]="1";Check(HardwareRules.Validate(twice).Count==0,"separate pins coexist");
   var singleton=HardwareCatalog.Snapshot(device.Template);singleton.MaxInstances=1;var singleDoc=MapDocument.Demo();singleDoc.Version=8;singleDoc.Devices=new List<DeviceInstance>{HardwareCatalog.Create(singleton),HardwareCatalog.Create(singleton)};Reject(()=>singleDoc.StructuralCheck(),"legacy singleton duplicate");
   var pwm=Fixture("pwm_servo");var pwm2=HardwareCatalog.Create(pwm.Devices[0].Template);pwm2.Configured=true;pwm.Devices.Add(pwm2);Check(HardwareRules.Validate(pwm).Any(e=>e.Contains("争用资源")),"PWM channel conflict");pwm2.Values["Channel"]="2";Check(HardwareRules.Validate(pwm).Count==0,"shared timer matching base period");pwm2.Values["PeriodUs"]="18000";Check(HardwareRules.Validate(pwm).Any(e=>e.Contains("争用资源")),"shared timer incompatible frequency");
   var can=MapDocument.Demo();can.Version=8;can.Application=new ApplicationSettings();var canTemplate=HardwareTemplateDialog.CreateBase("custom");canTemplate.Parameters.Add(new DeviceParameter{Key="Can",Name="CAN",Type="identifier",Default="hcan1"});canTemplate.Resources.Add(new DeviceResource{Kind="can_tx",Value="${Can}:0x200"});var canDevice=HardwareCatalog.Create(canTemplate);canDevice.Configured=true;can.Devices=new List<DeviceInstance>{canDevice};Check(HardwareRules.Validate(can).Any(e=>e.Contains("0x200")),"chassis whole-current-frame ownership");
   Reject(()=>HardwareRules.SafePath("CON.h"),"Windows reserved source path");Reject(()=>HardwareRules.SafePath("module./x.c"),"Windows path normalization collision");var emptyDone=HardwareTemplateDialog.CreateBase("custom");emptyDone.Hooks.Done="";Reject(()=>HardwareRules.TemplateCheck(emptyDone),"custom operation requires completion hook");
   var action=new RouteAction();HardwareOperations.BindAction(doc,action,device,device.Template.Operations[0],device.Template.Operations[0].DefaultValue);doc.Points[0].ArrivalActions.Add(action);Check(action.Start.Contains("return RCS_ACTION_ERROR")&&action.Condition.Contains(" > 0"),"command failure and positive-only completion");Check(HardwareRules.Referenced(doc,device.Id),"action dependency tracked");Check(doc.Clone().Points[0].ArrivalActions.Last().DeviceId==device.Id,"action binding persists");
   using(var manager=new HardwareManagerDialog(doc,Path.Combine(folder,"templates")))Reject(()=>manager.Remove(device),"referenced device removal");
   var machine=twice.Clone();machine.Application=new ApplicationSettings();var state=machine.Application.States[0];HardwareOperations.BindState(machine,state,machine.Devices[0],machine.Devices[0].Template.Operations[0],0);HardwareOperations.BindState(machine,state,machine.Devices[1],machine.Devices[1].Template.Operations[0],0);Check(state.Complete.Contains("&&")&&state.DeviceReferences.Count==2,"multiple device completion AND");Check(state.Enter.Contains("if (!rcs_hw_require_command(")&&state.Enter.Contains("return;"),"state command failure uses fault-latching requirement");Reject(()=>HardwareOperations.BindState(machine,state,machine.Devices[0],machine.Devices[0].Template.Operations[0],0),"same device cannot receive two goals in one state");Check(machine.Clone().Application.States[0].HardwareOperations.Count==2,"structured state operations persist");
   var terrain8=TerrainGeometry.Demo();terrain8.Version=8;terrain8.Devices=new List<DeviceInstance>{HardwareCatalog.Create(device.Template)};Check(terrain8.Clone().Json()==terrain8.Json(),"v8 hardware and terrain coexist");DraftRules.Terrain(terrain8);Check(terrain8.Version==8,"terrain editing preserves hardware schema");var correction8=CorrectionTests.Fixture();correction8.Version=8;correction8.Devices=new List<DeviceInstance>{HardwareCatalog.Create(device.Template)};Check(correction8.Clone().Json()==correction8.Json(),"v8 hardware and independent correction coexist");var app8=machine.Clone();app8.ImportChassis("#define RCS_LAYOUT 0\n#define RCS_WHEEL_DIAMETER_MM 100\n#define RCS_WHEELBASE_MM 300\n#define RCS_TRACK_MM 300\n#define RCS_OMNI_RADIUS_MM 200\n#define RCS_OMNI_THETA0_DEG 0\n#define RCS_GEAR_RATIO 19.2032\n#define RCS_MAX_MOTOR_RPM 3000\n#define RCS_CAN_BUS 1\n#define RCS_MOTOR_ID_0 1\n#define RCS_MOTOR_ID_1 2\n#define RCS_MOTOR_ID_2 3\n#define RCS_MOTOR_ID_3 4\n");Check(app8.Version==8&&app8.Devices.Count==2,"chassis import preserves hardware schema");
   var property=TypeDescriptor.GetProperties(new DeviceParameterView(device))["Pin"];property.SetValue(null,2);Check(device.Get("Pin")=="2"&&!device.Configured,"GUI edit invalidates confirmation");device.Configured=true;
   var disabled=doc.Clone();disabled.Points[0].ArrivalActions.Clear();disabled.Devices[0].Enabled=false;Check(HardwareRules.HasDevices(disabled),"disabled entries still need runtime header");var onlyHeader=MapDocument.Demo();onlyHeader.ActionIncludes=HardwareOperations.Include(onlyHeader.ActionIncludes);Check(HardwareRules.HasDevices(onlyHeader),"handwritten include retains stub");
   var personal=HardwareCatalog.Snapshot(device.Template);personal.Id="user_test_"+Guid.NewGuid().ToString("N");personal.Name="个人GPIO";var directory=Path.Combine(folder,"templates");string saved=HardwareCatalog.Save(personal,directory);Check(File.Exists(saved),"personal template persisted");Check(HardwareCatalog.LoadTemplates(directory).Any(t=>t.Id==personal.Id),"personal template loads without rebuilding EXE");Check(HardwareCatalog.Save(personal,directory)==saved,"same bytes repeat save is idempotent");var changed=HardwareCatalog.Snapshot(personal);changed.Note="new body";Reject(()=>HardwareCatalog.Save(changed,directory),"same version cannot silently replace");changed.Version="1.0.1";Check(File.Exists(HardwareCatalog.Save(changed,directory)),"explicit new version allowed");Reject(()=>HardwareCatalog.Save(catalog[0],directory),"builtin ID cannot be overwritten");
   var packaged=Path.Combine(folder,"export.rcshw.json");File.WriteAllText(packaged,HardwareCatalog.Json(personal),new UTF8Encoding(false));string imported=HardwareCatalog.Import(packaged,Path.Combine(folder,"imported"));Check(HardwareCatalog.Hash(HardwareCatalog.Parse(File.ReadAllText(imported)))==HardwareCatalog.Hash(personal),"portable template import/export exact");
   var badTemplate=HardwareCatalog.Snapshot(personal);badTemplate.Files.Add(new DeviceFile{Path="../escape.c",Content="int x;"});Reject(()=>HardwareRules.TemplateCheck(badTemplate),"source path traversal");badTemplate=HardwareCatalog.Snapshot(personal);badTemplate.Files.Add(new DeviceFile{Path="duplicate.c",Content="int x;"});badTemplate.Files.Add(new DeviceFile{Path="DUPLICATE.c",Content="int y;"});Reject(()=>HardwareRules.TemplateCheck(badTemplate),"case-insensitive source collision");
   var wizardBase=HardwareTemplateDialog.CreateBase("custom");Check(wizardBase.Hooks.Command.Contains("return 0")&&wizardBase.Hooks.Done.Contains("return 0"),"unknown custom driver never pretends complete");using(var wizard=new HardwareTemplateDialog(personal,directory))Check(HardwareCatalog.Hash(wizard.CaptureTemplate())==HardwareCatalog.Hash(personal),"GUI template form roundtrip");
   var isolated=doc.Clone();string untouched=doc.Json();using(var manager=new HardwareManagerDialog(isolated,directory)){manager.Add(catalog.First(t=>t.DriverKind=="pwm_servo"));manager.DialogResult=DialogResult.Cancel;}Check(doc.Json()==untouched,"manager cancel does not edit original");
   var observe=Fixture("team_jy901");using(var manager=new HardwareManagerDialog(observe,directory)){var source=manager.Observation(observe.Devices[0]);Check(source.Kind=="imu"&&source.Axes==4&&!source.Ready,"IMU becomes unaligned relative observation only");Check(source.ReadFunction=="rcs_hw_observation_"+observe.Devices[0].Id,"generated observer name matches instance");Check(manager.Observation(observe.Devices[0]).Id==source.Id,"observation creation idempotent");}Check(observe.Clone().Json()==observe.Json(),"observation-device v8 roundtrip");
   using(var editor=new Editor()){var field=typeof(Editor).GetField("doc",BindingFlags.Instance|BindingFlags.NonPublic);field.SetValue(editor,doc.Clone());editor.BeginChange();((MapDocument)field.GetValue(editor)).Devices[0].Name="改名";editor.EndChange();typeof(Editor).GetMethod("Undo",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(editor,null);Check(((MapDocument)field.GetValue(editor)).Json()==doc.Json(),"undo includes hardware snapshots");typeof(Editor).GetMethod("Redo",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(editor,null);Check(((MapDocument)field.GetValue(editor)).Devices[0].Name=="改名","redo includes hardware");}
   Write(Path.Combine(folder,"fixtures"));File.WriteAllText(Path.Combine(folder,"hardware-selftest.txt"),"PASS "+checks+" hardware model/catalog/UI/template/action checks\n",new UTF8Encoding(false));Console.WriteLine("PASS "+checks+" hardware model/catalog/UI/template/action checks");
  }
  public static void Render(string path,bool authoring=false){var doc=Fixture("team_cylinder");var second=HardwareCatalog.Create(HardwareCatalog.Builtins().First(t=>t.DriverKind=="team_jy901"));second.Values["Uart"]="huart3";doc.Devices.Add(second);using(Form dialog=authoring?(Form)new HardwareTemplateDialog(HardwareTemplateDialog.CreateBase("custom"),Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"render-user-templates")):new HardwareManagerDialog(doc,Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"render-user-templates"))){dialog.ShowInTaskbar=false;dialog.Opacity=0;dialog.Show();dialog.Refresh();Application.DoEvents();using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(path,System.Drawing.Imaging.ImageFormat.Png);}dialog.Close();}}
 }
}
